package instance

import (
	"html/template"
	"net/http"
)

func (i *Instance) voiceSettingsPage(w http.ResponseWriter, r *http.Request) {
	if _, _, ok := i.authenticated(w, r); !ok {
		return
	}
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	_ = voiceSettingsTemplate.Execute(w, nil)
}

var voiceSettingsTemplate = template.Must(template.New("voice-video-settings").Parse(`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Voice &amp; Video — AllChat</title><link rel="stylesheet" href="/assets/app.css"><script src="/assets/app.js" defer></script><script src="/assets/voice-settings-page.js" defer></script></head><body><div class="app-shell"><aside class="community-rail"><a class="community-mark" href="/">AC</a></aside><aside class="channel-sidebar"><div class="community-header">Member Settings</div><nav class="channel-nav settings-nav"><a href="/profile">My Account</a><a href="/voice-video" aria-current="page">Voice &amp; Video</a><a href="/sessions">Sessions</a><a href="/search">Search</a><a href="/">Back to Community</a></nav></aside><main class="content-shell"><header class="content-header"><button class="mobile-menu" type="button" data-sidebar-toggle aria-label="Open settings navigation" aria-expanded="false">☰</button><h1>Voice &amp; Video</h1></header><section class="content voice-settings" data-voice-settings><h2 class="page-title">Devices and processing</h2><p class="page-description">These preferences stay in this browser. Device and processing changes apply to the next call.</p><div class="card"><label>Microphone<select name="microphoneID"><option value="">System default</option></select></label><label>Speaker<select name="speakerID"><option value="">System default</option></select></label><label>Camera<select name="cameraID"><option value="">System default</option></select></label><video data-camera-preview autoplay muted playsinline hidden></video><button type="button" class="button-ghost" data-camera-test>Test camera</button></div><div class="card"><label><input type="checkbox" name="echoCancellation"> Echo cancellation</label><label>Noise suppression<select name="noiseSuppressionMode"><option value="standard">Standard (WebRTC)</option><option value="enhanced">Enhanced (RNNoise)</option><option value="off">Off</option></select></label><p class="muted">Enhanced suppression runs locally and retains WebRTC echo cancellation. It never sends microphone audio to a third party.</p><label><input type="checkbox" name="autoGainControl"> Automatic gain control</label><label><input type="checkbox" name="noiseGate"> Noise gate</label><label>Microphone level <meter min="-80" max="0" value="-80" data-microphone-meter></meter></label><label>Gate threshold <output data-gate-output></output><input type="range" name="noiseGateThresholdDB" min="-80" max="-20" step="1"></label><label>Outgoing microphone volume <output data-input-output></output><input type="range" name="inputGain" min="0" max="2" step="0.05"></label><label>Incoming voice volume <output data-volume-output></output><input type="range" name="outputVolume" min="0" max="1" step="0.05"></label><button type="button" class="button-ghost" data-output-test>Test speaker</button></div><p class="muted" data-voice-notice role="status"></p></section></main></div></body></html>`))
